window.products.push({"id":723371,"name":"Ebros Gift African Bush Elephant Glass Salt & Pepper Shakers Holder Figurine Decor 7\"H","category":"homeandappliances","retail price":24.95,"sale price":null,"image":"https://m.media-amazon.com/images/I/71nvHeCbC3L._AC_SL1500_.jpg","description":"This African Elephant Salt & Pepper Shakers Holder figurine measures at 7\" Tall, 5.25\" Long and 5\" Deep approximately. This listing comes with the figurine and the two shakers as pictured. This African Elephant Salt & Pepper Shakers Holder figurine is made of cold cast resin, hand painted and polished. Color tone may vary. This adorable elephant figurine is a beautiful centerpiece for any dining table! If you love the safari scene and especially giant elephants, you cannot go wrong with this figurine!","images":["https://m.media-amazon.com/images/I/71nvHeCbC3L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Ebros Gift","source_asin":"B074SZJ6JW","category_path":"Home & Kitchen"},"sku":"BM-723371","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B074SZJ6JW","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B074SZJ6JW","price_pending":true,"merchant_ready":false});
